"""Finish the draft's rare-ID and transfer explanations without accepting it."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
paragraphs={
'Rare categories получают мало':'''Редкие категории получают мало обновлений по данным. Объединение редких значений, меньшую размерность, затухание весов, ограничения нормы и общие признаки объекта сравнивают на проверочной части. Строке UNK нужен обучающий сигнал, например при контролируемом скрытии известных категорий. Случайно инициализированная строка для нового ID не знает его индивидуального эффекта.''',
'Словарь сохраняется вместе с weights':'''Словарь сохраняют вместе с весами. Если при загрузке переставить ID, поиск вернёт неправильные строки без ошибки формы. Пропуск, PAD и UNK могут требовать отдельных строк; правила обновления PAD зависят от реализации и требуют проверки.''',
'Для K=10 000,d=16 имеем':'''При K=10 000 и d=16 таблица содержит 160 000 параметров, или 640 000 байт весов float32. Плотный градиент и два состояния Adam той же точности добавят 1 920 000 байт; вместе получится 2 560 000 байт без активаций, накладных расходов и остальных слоёв. При смешанной точности основные копии весов и типы градиентов могут изменить расчёт.''',
'One-hot input с одной активной':'''One-hot вход с одной активной категорией на объект можно хранить разреженно; скалярная линейная модель имеет для него всего K коэффициентов. Таблица с d=16 содержит в 16 раз больше параметров, хотя выдаёт компактный вектор на каждый пример. При K=1 000 000,d=64 одни веса float32 занимают 256 MB в десятичных единицах; веса, градиент и два состояния Adam — 1.024 GB. Компактность на выходе не гарантирует меньшей памяти всей системы.''',
'Batch B×d activations зависят':'''Активации пакета B×d зависят от числа обращений к таблице, а сама таблица — от Kd. Разреженный градиент может уменьшить работу с затронутыми строками, но не делает веса бесплатными. Разделение таблицы между устройствами или перенос части данных увеличивает стоимость обмена и задержку.''',
'Если category встречается r раз':r'''Если категория встречается r раз, её строка получает непосредственный сигнал примерно при этих r обращениях за проход, с поправкой на выборку. Рост d с 8 до 128 добавляет свободные координаты, а не наблюдения. При частоте p вероятность не встретить ID в B независимых выборках равна $(1-p)^B$. Для p=0.0001 и B=256 она около 0.9747: большинство таких пакетов не дают этому ID прямого градиента.''',
'Oversampling rare categories меняет':r'''Более частое включение редких категорий меняет частоту обновлений и при неправильных весах может изменить целевую популяцию. Затухание весов к нулю задаёт простое предположение, но нулевой вектор не обязательно описывает среднее поведение. Альтернатива — использовать доступные свойства объекта: $e_c=g(x_c)+r_c$, где g строит вектор по свойствам, а r_c — индивидуальная поправка. Для нового ID можно положить поправку равной нулю и использовать свойства, если они доступны к моменту прогноза.''',
'При category dropout во время training':'''При скрытии категорий (category dropout) во время обучения часть известных ID заменяют на UNK. Строка UNK учится на распределении скрытых примеров, а не получает автоматически смысл всех будущих объектов. Если выбор равномерен по строкам, в сигнале преобладают частые ID; если по категориям, задача меняется. Долю скрытия и схему сравнивают на проверке с отдельными срезами известных, редких и новых значений.''',
'Для новой category со stable metadata':'''Для новой категории с доступными свойствами можно построить резервное представление по этим свойствам. Для произвольного ID без свойств индивидуальную информацию получить неоткуда. Создание случайной строки на каждом запросе не даёт осмысленной персонализации. При расширении словаря фиксируют версию, правило инициализации и при продолжении обучения расширяют состояние оптимизатора; перестановка старых строк нарушает соответствие.''',
'При переносе между tasks нужны':'''Для переноса между задачами нужны стабильные ID, совместимые словари, доступные источники и проверка отрицательного переноса. Исходная задача могла закрепить смещение старого периода, а дообучение — забыть полезную структуру. Замороженную и обновляемую таблицы сравнивают на одном разбиении с отдельной оценкой редких и новых объектов.''',
'Embedding — обычный trainable parameter':'''Таблица векторов — обычный обучаемый параметр модели. Её обучение по разрешённым обучающим меткам не требует автоматически исключать каждую строку из собственного градиента: иначе пришлось бы запретить и обычное обучение с учителем. Обобщение проверяют на внешних данных, чьи метки не участвовали в обучении таблицы, головы или подборе параметров.''',
'Для переноса фиксируют source entity':'''Для переноса фиксируют определение объекта в исходной задаче, словарь, временную границу и цель обучения. Один числовой ID в разных системах может означать разные объекты; совпадение формы таблиц не гарантирует совместимости. Исходные метки из будущего относительно оценки новой задачи могут нарушать временной протокол, даже если набор называется независимым.''',
'Frozen table сохраняет source representation':'''Замороженная таблица сохраняет исходное представление, но новая голова ограничена доступной в нём информацией. Дообучение адаптирует известные строки, но может ухудшить исходную геометрию или забыть старую структуру. Сравнение со случайной инициализацией и моделью только по свойствам объекта помогает отделить полезный перенос от дополнительной ёмкости. Качество на известных ID не доказывает качество для новых объектов.''',
'Идея embeddings распространяется':r'''Идея векторного представления применима не только к ID: кодировщик $f_\theta$ преобразует объект $x$ в вектор $z=f_\theta(x)\in\mathbb R^d$. Текстовый кодировщик может объединять состояния токенов, а кодировщик изображения — пространственную карту признаков. Геометрия зависит от цели предобучения, объединения, нормировки и области данных; одинаковая размерность разных моделей не делает их оси одинаковыми.''',
'Frozen encoder преобразует':'''Замороженный кодировщик преобразует обучающие, проверочные и новые объекты одной фиксированной функцией. Это удобный базовый вариант, если его состояние независимо от проверочных меток, но различие областей данных может ограничить качество. Дообучение меняет параметры под новую задачу и может забыть исходную структуру. Кодировщик и обучаемые нормализацию или PCA располагают внутри разрешённой обучающей части либо используют независимо предобученные компоненты по объявленному протоколу.''',
'Для out-of-sample применения':'''Для применения к новым объектам сохраняют версию модели, предварительную обработку, способ объединения, размерность, нормировку и правила некорректного или отсутствующего входа. Если после кодировщика используют PCA или другую обучаемую проекцию, её параметры тоже сохраняют и не пересчитывают по новым объектам.'''
}
def op(t):
 for prefix,new in paragraphs.items():
  a=t.find(prefix)
  if a<0:raise ValueError('Missing paragraph: '+prefix)
  ends=[i for i in (t.find('\n\n',a),t.find('\n<!-- EDIT:',a),t.find('\n<!-- /EDIT:',a)) if i>=0]
  if not ends:raise ValueError('Missing boundary: '+prefix)
  b=min(ends);t=t[:a]+new+t[b:]
 return t
c=load();transform('01-data-features/02-features/feat-embeddings.md',op,
 'Пакет 03: редактура редких ID, памяти и переноса представлений с сохранением ограничений; содержательная приёмка ожидается.',c);save(c)
print('Rare IDs and transfer edited; review remains open.')
